def _bind_to_schema(self, field_name, schema):
    super()._bind_to_schema(field_name, schema)
    # Ensure we inspect the root Schema's opts, not an intermediate
    # container field (e.g. List or Tuple) that has no "opts" attribute.
    root_schema = getattr(self, "root", schema)
    field_factory = self._get_formatting_info_from_schema(field_name, root_schema)
    if field_factory:
        self._format = field_factory
    if self.load_only:
        self._deserialize_from = self._format
    if self.dump_only:
        self._serialize_to = self._format

